    {
      "id": 1,
      "claim": "For a concave mirror the mirror equation is 1/f = 1/do + 1/di, where f>0.",
      "evidence": "Standard optics formula for spherical mirrors.",
      "weight": 0.2,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "When the object is far (do >> f), 1/do ≈ 0, so 1/di ≈ 1/f and di ≈ f.",
      "evidence": "Substituting a very large do into the mirror equation simplifies it.",
      "weight": 0.2,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "As do decreases toward f, the term 1/do grows, making 1/di = 1/f – 1/do smaller, so di becomes larger, approaching infinity when do = f.",
      "evidence": "Algebraic rearrangement of the mirror equation.",
      "weight": 0.3,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "The linear magnification is m = –di/do; its magnitude |m| = di/do increases as di grows and do shrinks, so the image gets taller (more magnified).",
      "evidence": "Definition of magnification for mirrors.",
      "weight": 0.2,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Therefore, as the object moves from far away to near the focal point, the image moves farther from the mirror and becomes taller.",
      "evidence": "Combining steps 3 and 4.",
      "weight": 0.1,
      "depends_on": [3, 4]
    }
  ],
